// Sceglie UNO Short a ogni giro per TikTok (Marco, 11/11/2026: «renderla automatica la pubblicazione», via Buffer).
// Solo gli Short (video-breve-*), in inglese, degli ultimi 7 giorni: per un canale nuovo prima le notizie più fresche.
// La memoria resta fra un giro e l'altro solo quando il flusso è ATTIVO (le prove a mano non se la ricordano).
const memoria = $getWorkflowStaticData('global');
memoria.fatti = memoria.fatti || [];
// TikTok: circa 15 post al giorno per account (regole ufficiali, lette l'11/11/2026); Buffer Free: 10 post in coda per canale
// e 600 richieste al giorno. Tetto a 3 al giorno: il flusso gira 3 volte al giorno, uno per giro.
const TETTO = 3;
const giorno = new Date().toLocaleDateString('en-CA', { timeZone: 'Europe/Rome' });
if (memoria.giorno !== giorno) { memoria.giorno = giorno; memoria.oggi = 0; }
if ((memoria.oggi || 0) >= TETTO) return [];
const limite = new Date(Date.now() - 7 * 864e5).toISOString();
const pronti = [];
for (const it of $('Leggi i video pronti su GitHub').all()) {
  const r = it.json;
  const tag = String(r.tag_name || '');
  if (!tag.startsWith('video-breve-') || tag.endsWith('-it') || r.draft || memoria.fatti.includes(tag)) continue;
  if (String(r.created_at) < limite) continue;
  const file = (fine) => (r.assets || []).find((a) => a.name.endsWith(fine));
  if (!file('.mp4') || !file('.json')) continue;
  pronti.push({ tag, creato: r.created_at, mp4: file('.mp4').browser_download_url, info: file('.json').browser_download_url });
}
if (!pronti.length) return [];
pronti.sort((a, b) => b.creato.localeCompare(a.creato));
return [{ json: { ...pronti[0], inCoda: pronti.length, oggi: memoria.oggi || 0 } }];

// Il canale TikTok collegato a Buffer. Se manca, il flusso si ferma con un errore chiaro e non pubblica niente
// (come il controllo del canale giusto nel flusso YouTube, 23/10/2026).
const canali = $json.data?.channels || [];
const tiktok = canali.filter((c) => String(c.service).toLowerCase() === 'tiktok');
if (tiktok.length !== 1) throw new Error(`Serve esattamente un canale TikTok in Buffer, trovati ${tiktok.length}: ${JSON.stringify(canali.map((c) => [c.service, c.name]))}`);
if (tiktok[0].isQueuePaused) throw new Error(`La coda Buffer di ${tiktok[0].name} è in pausa: riattivarla in Buffer.`);
return [{ json: { canale: tiktok[0].id, nome: tiktok[0].name } }];

// Testo del post TikTok: titolo senza #Shorts, la frase della notizia e il sito. Su TikTok i link non si cliccano:
// resta il nome del sito (la voce del video dice «link in bio»). Buffer: al massimo 5 hashtag per post (support.buffer.com, 11/11/2026).
const scelto = $('Scegli lo Short').first().json;
const info = $('Leggi titolo e descrizione').first().json;
const canale = $('Solo il canale TikTok').first().json.canale;
const titolo = String(info.titolo || '').replace(/#shorts/gi, '').trim();
const frase = String(info.descrizione || '').split('\n')[0].trim();
const hashtag = ['#AI', '#AInews', '#LLM', '#FreeLLMArena'];
const testo = [titolo, frase && frase !== titolo ? frase : '', 'More on freellmarena.com', hashtag.join(' ')].filter(Boolean).join('\n\n').slice(0, 2000);
if (!titolo || !/^https:\/\//.test(scelto.mp4)) throw new Error('Dati dello Short incompleti: ' + JSON.stringify({ tag: scelto.tag, titolo, mp4: scelto.mp4 }));
// JSON.stringify produce una stringa valida anche per GraphQL (stesse sequenze di escape)
const query = `mutation CreatePost { createPost(input: { text: ${JSON.stringify(testo)} channelId: ${JSON.stringify(canale)} schedulingType: automatic mode: addToQueue assets: [ { video: { url: ${JSON.stringify(scelto.mp4)} } } ] }) { ... on PostActionSuccess { post { id text } } ... on MutationError { message } } }`;
return [{ json: { tag: scelto.tag, testo, query } }];

// Segna lo Short come mandato a Buffer, così non riparte. Se Buffer risponde con un errore, il flusso si ferma e lo mostra.
const memoria = $getWorkflowStaticData('global');
